#include "CowbellEngineBanks.h"
namespace lr608{namespace{constexpr const char*ids[]{"slider080","slider081","slider082","slider083","slider084","slider085","slider086","slider087","slider088","slider089","slider204"};constexpr float factory[7][11]{{8,.32f,.45f,.55f,1,.4f,.35f,.3f,10,.25f,1},{6,.5f,2,.5f,0,.5f,.5f,0,0,0,1},{6,.1f,2,.5f,10,5,.5f,0,0,0,1},{9,0,2.3f,0,1,.4f,.35f,.3f,5,.25f,1},{6,.5f,2,.5f,0,.5f,.5f,0,0,0,1},{5,.8f,2.75f,1,4.5f,5,.7f,.3f,3.5f,.18f,.16f},{5,.8f,2.75f,1,4.5f,5,.7f,.3f,3.5f,.18f,.16f}};}
CowbellEngineBanks::CowbellEngineBanks(juce::AudioProcessorValueTreeState&s):state(s){resetToFactory();}void CowbellEngineBanks::resetFromCurrentState(){for(int e=0;e<7;++e)for(int p=0;p<11;++p)banks[e][p]=factory[e][p];currentEngine=juce::jlimit(0,6,juce::roundToInt(state.getRawParameterValue("slider215")->load()));captureCurrent();}void CowbellEngineBanks::resetToFactory(){for(int e=0;e<7;++e)for(int p=0;p<11;++p)banks[e][p]=factory[e][p];currentEngine=juce::jlimit(0,6,juce::roundToInt(state.getRawParameterValue("slider215")->load()));load(currentEngine);}bool CowbellEngineBanks::ownsParameter(juce::StringRef id){for(auto*x:ids)if(id==juce::StringRef(x))return true;return false;}void CowbellEngineBanks::captureCurrent(){if(applying)return;for(int p=0;p<11;++p)banks[currentEngine][p]=state.getRawParameterValue(ids[p])->load();}void CowbellEngineBanks::load(int e){const juce::ScopedValueSetter g(applying,true);for(int p=0;p<11;++p)if(auto*x=state.getParameter(ids[p]))x->setValueNotifyingHost(x->convertTo0to1(banks[e][p]));}bool CowbellEngineBanks::switchTo(int e){e=juce::jlimit(0,6,e);if(e==currentEngine||applying)return false;captureCurrent();currentEngine=e;load(e);return true;}}
